                    "definition": "<em>a body of prophetic</em> (or sometimes perhaps priestly) <em>teaching</em> <a data-ref=\"Isaiah 42:21\" href=\"/Isaiah.42.21\">Is 42:21</a>, <a data-ref=\"Isaiah 42:24\" href=\"/Isaiah.42.24\">24</a> <a data-ref=\"Jeremiah 9:12\" href=\"/Jeremiah.9.12\">Je 9:12</a>; <a data-ref=\"Jeremiah 16:11\" href=\"/Jeremiah.16.11\">16:11</a>; in the heart <a data-ref=\"Isaiah 51:7\" href=\"/Isaiah.51.7\">Is 51:7</a> <a data-ref=\"Psalms 37:31\" href=\"/Psalms.37.31\">ψ 37:31</a>; <a data-ref=\"Psalms 40:9\" href=\"/Psalms.40.9\">40:9</a>; ‖ <span dir=\"rtl\">משׁפט</span> <a data-ref=\"Habakkuk 1:4\" href=\"/Habakkuk.1.4\">Hb 1:4</a>; ‖ <span dir=\"rtl\">משׁפטים</span> <a data-ref=\"Psalms 89:31\" href=\"/Psalms.89.31\">ψ 89:31</a>; ‖ <span dir=\"rtl\">דְּבָרִים</span> <a data-ref=\"Jeremiah 6:19\" href=\"/Jeremiah.6.19\">Je 6:19</a>; <a data-ref=\"Jeremiah 26:4\" href=\"/Jeremiah.26.4\">26:4</a> <a data-ref=\"Zechariah 7:12\" href=\"/Zechariah.7.12\">Zc 7:12</a>; ‖ <span dir=\"rtl\">חקים</span> <a data-ref=\"Amos 2:4\" href=\"/Amos.2.4\">Am 2:4</a>; ‖ <span dir=\"rtl\">חקות</span> <a data-ref=\"Jeremiah 44:10\" href=\"/Jeremiah.44.10\">Je 44:10</a>, <a data-ref=\"Jeremiah 44:23\" href=\"/Jeremiah.44.23\">23</a>; myriads of precepts <a data-ref=\"Hosea 8:12\" href=\"/Hosea.8.12\">Ho 8:12</a>."
