      "derivatives": "Derivative: <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_שֶׁלֶם ᴵᴵ.1\" data-ref=\"Klein Dictionary, שֶׁלֶם ᴵᴵ 1\">שׁלם ᴵᴵ</a>. cp. <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_שְׁלָמָא.1\" data-ref=\"Klein Dictionary, שְׁלָמָא 1\">שְׁלָמָא</a>.",
      "prev_hw": "שְׁלוּלִית",
      "next_hw": "שָׁלוּם",
      "notes": "[For the etymology of <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_שָׁלוֹם.1\" data-ref=\"Klein Dictionary, שָׁלוֹם 1\">שָׁלוֹם</a> see <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_שׁלה ᴵ.1\" data-ref=\"Klein Dictionary, שׁלה ᴵ 1\">שׁלה</a>, to which it stands as <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_עָרוּם ᴵ.1\" data-ref=\"Klein Dictionary, עָרוּם ᴵ 1\">עֵרוֹם</a> (= naked), stands to <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_ערה ᴵ.1\" data-ref=\"Klein Dictionary, ערה ᴵ 1\">ערה ᴵ</a> (= to lay bare). cp. the related BAram. <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_שֶֽׁלֶם ᴵ.1\" data-ref=\"Klein Dictionary, שֶֽׁלֶם ᴵ 1\">שְׁלָם</a>, Aram. <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_שֶֽׁלֶם ᴵ.1\" data-ref=\"Klein Dictionary, שֶֽׁלֶם ᴵ 1\">שְׁלָם</a>, <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_שְׁלָמָא.1\" data-ref=\"Klein Dictionary, שְׁלָמָא 1\">שְׁלָמָא</a> (= completeness, welfare, peace), OAram. <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_שׁלם.1\" data-ref=\"Klein Dictionary, שׁלם 1\">שׁלם</a> (= reward, repay), Ugar. <i>shlm</i> (= peace), Arab. <i>silm</i> and <i>salam</i> (= safety, security), OSArab. <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_סלם.1\" data-ref=\"Klein Dictionary, סלם 1\">סלם</a> (= peace), Ethiop. <i>salām</i> (= security, peace), Akka. <i>shalāmu, shulmu</i> (= welfare).]",
