      "language_reference": " <a dir=\"rtl\" class=\"refLink\" href=\"/Jastrow,_חָכַם.1\" data-ref=\"Jastrow, חָכַם 1\"><a dir=\"rtl\" class=\"refLink\" href=\"/Jastrow,_חָכַם.1\" data-ref=\"Jastrow, חָכַם 1\">חָכַם</a>)</a>",
      "content": {
        "senses": [
          {
            "definition": "<i>wisdom, learning, art</i>. <a class=\"refLink\" href=\"/Berakhot.17a.11\" data-ref=\"Berakhot 17a:11\">Ber. 17ᵃ</a> <span dir=\"rtl\">תכלית ח׳ וכ׳</span> the perfection of wisdom is repentance and good deeds. <a class=\"refLink\" href=\"/Berakhot.33a.17\" data-ref=\"Berakhot 33a:17\">Ib. 33ᵃ</a> <span dir=\"rtl\">ברכת ח׳</span> the benediction of wisdom (the fourth of the Prayer of Benedictions). <a class=\"refLink\" href=\"/Bereishit_Rabbah.17.5\" data-ref=\"Bereishit Rabbah 17:5\">Gen. R. s. 17</a> <span dir=\"rtl\">חָכְמָתוֹ מרובה וכ׳</span> his (Adam’s) wisdom is greater than yours. <a class=\"refLink\" href=\"/Rosh_Hashanah.29b.9\" data-ref=\"Rosh Hashanah 29b:9\">R. Hash. 29ᵇ</a> <span dir=\"rtl\">שהיא ח׳ ואינה מלאכה</span> it is an art and not a labor; a. v. fr.—לשון ח׳ <i>enigmatical speech</i>. <a class=\"refLink\" href=\"/Eruvin.53b.13\" data-ref=\"Eruvin 53b:13\">Erub. 53ᵇ</a>.—<span dir=\"rtl\">חָכְמַת יונית</span>, v. <a dir=\"rtl\" class=\"refLink\" href=\"/Jastrow,_יְוָנִי.1\" data-ref=\"Jastrow, יְוָנִי 1\">יְוָנִי</a>."
          }
        ],
        "morphology": "f."
      },
