      "notes": "[Formed from <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_חכם.1\" data-ref=\"Klein Dictionary, חכם 1\">חכם</a> with first suff. <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_◌ָה ᴵ.1\" data-ref=\"Klein Dictionary, ◌ָה ᴵ 1\">◌ָה</a>. cp. Ugar. <i>ḥkmt</i> (= wisdom). cp. also <a dir=\"rtl\" class=\"refLink\" href=\"/Klein Dictionary,_חָכְמוֹת.1\" data-ref=\"Klein Dictionary, חָכְמוֹת 1\">חָכְמוֹת</a>.]",
